pub fn overflow_tests() -> Vec<(&'static [u8], &'static str)> {
    vec![
        (&b"128"[..], "int8"),
        (&b"32768"[..], "int16"),
        (&b"-129"[..], "int8"),
        (&b"-32769"[..], "int16"),
        (&b"256"[..], "uint8"),
        (&b"65536"[..], "uint16"),
        (&b"1e100"[..], "float32"),
        (&b"1e500"[..], "float64"),
        (&b"(1e100+0i)"[..], "complex64"),
        (&b"(1+1e100i)"[..], "complex64"),
        (&b"(1-1e500i)"[..], "complex128"),
    ]
}

pub fn multi_tests() -> Vec<MultiRow> {
    vec![
        (&b""[..], &b""[..], vec![], Some(vec![]), ""),
        (&b"%d"[..], &b"23"[..], vec!["int"], Some(vec![Value::Int(23, IntKind::Int)]), ""),
        (&b"%2s%3s"[..], &b"22333"[..], vec!["string", "string"], Some(vec![Value::String(b"22".to_vec()), Value::String(b"333".to_vec())]), ""),
        (&b"%2d%3d"[..], &b"44555"[..], vec!["int", "int"], Some(vec![Value::Int(44, IntKind::Int), Value::Int(555, IntKind::Int)]), ""),
        (&b"%2d.%3d"[..], &b"66.777"[..], vec!["int", "int"], Some(vec![Value::Int(66, IntKind::Int), Value::Int(777, IntKind::Int)]), ""),
        (&b"%d, %d"[..], &b"23, 18"[..], vec!["int", "int"], Some(vec![Value::Int(23, IntKind::Int), Value::Int(18, IntKind::Int)]), ""),
        (&b"%3d22%3d"[..], &b"33322333"[..], vec!["int", "int"], Some(vec![Value::Int(333, IntKind::Int), Value::Int(333, IntKind::Int)]), ""),
        (&b"%6vX=%3fY"[..], &b"3+2iX=2.5Y"[..], vec!["complex128", "float64"], Some(vec![Value::Complex128(f64::from_bits(0x4008000000000000), f64::from_bits(0x4000000000000000)), Value::Float64(f64::from_bits(0x4004000000000000))]), ""),
        (&b"%d%s"[..], &b"123abc"[..], vec!["int", "string"], Some(vec![Value::Int(123, IntKind::Int), Value::String(b"abc".to_vec())]), ""),
        (&b"%c%c%c"[..], &b"2\xe5\x83\x82X"[..], vec!["int32", "int32", "int32"], Some(vec![Value::Int(50, IntKind::Int32), Value::Int(20674, IntKind::Int32), Value::Int(88, IntKind::Int32)]), ""),
        (&b"%5s%d"[..], &b" 1234567 "[..], vec!["string", "int"], Some(vec![Value::String(b"12345".to_vec()), Value::Int(67, IntKind::Int)]), ""),
        (&b"%5s%d"[..], &b" 12 34 567 "[..], vec!["string", "int"], Some(vec![Value::String(b"12".to_vec()), Value::Int(34, IntKind::Int)]), ""),
        (&b"%e%f"[..], &b"eefffff"[..], vec!["Xs", "Xs"], Some(vec![Value::named("fmt_test.Xs", Value::String(b"ee".to_vec())), Value::named("fmt_test.Xs", Value::String(b"fffff".to_vec()))]), ""),
        (&b"%4v%s"[..], &b"12abcd"[..], vec!["IntString", "string"], Some(vec![strukt("fmt_test.IntString", vec![("i", Value::Int(12, IntKind::Int)), ("s", Value::String(b"ab".to_vec()))]), Value::String(b"cd".to_vec())]), ""),
        (&b"%t"[..], &b"23 18"[..], vec!["int"], None, "bad verb"),
        (&b"%d %d %d"[..], &b"23 18"[..], vec!["int", "int"], Some(vec![Value::Int(23, IntKind::Int), Value::Int(18, IntKind::Int)]), "too few operands"),
        (&b"%d %d"[..], &b"23 18 27"[..], vec!["int", "int", "int"], Some(vec![Value::Int(23, IntKind::Int), Value::Int(18, IntKind::Int)]), "too many operands"),
        (&b"%c"[..], &b"\xc4\x80"[..], vec!["int8"], None, "overflow"),
        (&b"X%d"[..], &b"10X"[..], vec!["int"], None, "input does not match format"),
        (&b"%d%"[..], &b"42%"[..], vec!["int"], Some(vec![Value::Int(42, IntKind::Int)]), "missing verb: % at end of format string"),
        (&b"%d% "[..], &b"42%"[..], vec!["int"], Some(vec![Value::Int(42, IntKind::Int)]), "too few operands for format '% '"),
        (&b"%%%d"[..], &b"xxx 42"[..], vec!["int"], Some(vec![Value::Int(42, IntKind::Int)]), "missing literal %"),
        (&b"%%%d"[..], &b"x42"[..], vec!["int"], Some(vec![Value::Int(42, IntKind::Int)]), "missing literal %"),
        (&b"%%%d"[..], &b"42"[..], vec!["int"], Some(vec![Value::Int(42, IntKind::Int)]), "missing literal %"),
        (&b"%c%c%c"[..], &b"\xc2X\xc2"[..], vec!["int32", "int32", "int32"], Some(vec![Value::Int(65533, IntKind::Int32), Value::Int(88, IntKind::Int32), Value::Int(65533, IntKind::Int32)]), ""),
        (&b"%v%v"[..], &b"FALSE23"[..], vec!["bool", "int"], Some(vec![Value::Bool(false), Value::Int(23, IntKind::Int)]), ""),
    ]
}

